/* Juan Dela Cruz's resume: one stylesheet for all three pages */

/* Element selectors: every body, h1, h2 and nav */
body {
  font-family: Verdana, Tahoma, sans-serif;
  line-height: 1.5;
  color: rgb(34, 34, 34);
}
h1 {
  font-family: Georgia, "Times New Roman", serif;
  color: #ffffff;
  text-transform: uppercase;
  background-image: linear-gradient(to right, #13305c, #8a1c55);
  text-align: center;
  letter-spacing: 2px;
  line-height: 2;
  position: relative;
}
h2 {
  font-family: Georgia, "Times New Roman", serif;
  color: #8a1c55;
  border-bottom: 2px solid #8a1c55;
  padding-bottom: 0.25em;
  margin-top: 1.5em;
  clear: both;
}
nav {
  font-weight: bold;
  text-transform: uppercase;
  background-color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 2;
}

/* Descendant selector: the list inside nav */
nav ul {
  list-style-type: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: row;
  gap: 0.5em;
}

/* Flexbox puts the nav items in a row, so each one is a box of its own and gap makes the space */
nav li {
  margin-right: 0;
}

/* Link states, in this order: :link, :visited, :hover, :active */
a:link {
  color: #13305c;
}
a:visited {
  color: #551a8b;
}
a:hover, a:focus {
  background-color: #fff3c4;
}
a:active {
  color: #8a1c55;
}

/* Nav links: white on navy; maroon under the mouse or keyboard */
nav a:link, nav a:visited {
  color: #ffffff;
  background-color: #13305c;
  padding: 0.25em 0.75em;
  text-decoration: none;
}
nav a:hover, nav a:focus {
  background-color: #8a1c55;
}

/* Class selector: every element with class="badge" */
.badge {
  background-image: linear-gradient(#fff3c4, #ffe08a);
  font-size: 12px;
  padding: 0.25em 0.5em;
  border: 1px solid #b45309;
  float: right;
}

/* Lists: no bullets for the skills (a tick comes from ::before, below); Roman numbers. Flexbox: one skill under the other, with a gap */
.skills {
  list-style-type: none;
  list-style-position: inside;
  padding-left: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5em;
}
.next {
  list-style-type: upper-roman;
}

/* Element selector: every paragraph */
p {
  color: #333333;
}

/* Element selector: every label */
label {
  font-weight: bold;
  font-size: 1.1em;
}

/* A comma lists several selectors: every form box 300px wide, padding and border included */
input, select, textarea {
  box-sizing: border-box;
  width: 300px;
  padding: 4px;
  border: 1px solid #555555;
}

/* Element selector: small print, faded with opacity */
small {
  opacity: 0.75;
}

/* ID selector: only the element with id="form-note" */
#form-note {
  color: #9b1c1c;
  font-weight: bold;
  font-style: italic;
}

/* The framed contact page: solid border, space above */
iframe {
  border: 2px solid #13305c;
  margin-top: 0.5em;
}

/* Position: the ribbon sits 8px from the top-right corner of its h1, above it */
.ribbon {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 1;
  padding: 0 0.5em;
  font-size: 12px;
  color: #222222;
  background-color: #fff3c4;
}

/* Flexbox instead of float: the figures sit side by side and wrap to the next line when they do not fit */
.gallery {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.gallery figure {
  width: 170px;
  position: relative;
}

/* Float: Juan's picture on the left; the introduction wraps beside it */
.profile {
  float: left;
  margin: 0 1em 0.5em 0;
}

/* Gallery: every picture the same size in px, a caption under it */
.gallery img {
  width: 160px;
  height: 110px;
  border: 1px solid #555555;
}
.gallery figcaption {
  font-size: 13px;
  text-align: center;
}

/* Position: a tag in the top-left corner of its figure, above the picture */
.tag {
  position: absolute;
  top: 4px;
  left: 4px;
  z-index: 1;
  padding: 0 0.4em;
  font-size: 12px;
  color: #ffffff;
  background-color: #8a1c55;
}

/* Pseudo-classes: a skill under the mouse turns light yellow; the first skill, Juan's best, stands out */
.skills li:hover {
  background-color: #fff3c4;
}
.skills li:first-child {
  font-weight: bold;
  text-transform: uppercase;
}

/* Pseudo-element: only the first letter of each badge is a capital */
.badge::first-letter {
  text-transform: uppercase;
}

/* Pseudo-classes on the form: every box that must be filled has a maroon border */
input:required {
  border-color: #8a1c55;
}

/* The box you click or Tab into gets a maroon outline */
input:focus, select:focus, textarea:focus {
  outline: 3px solid #8a1c55;
}

/* The button: white on maroon under the mouse and the keyboard alike */
button:hover, button:focus {
  color: #ffffff;
  background-color: #8a1c55;
}

/* Links: a maroon outline when the keyboard reaches a link, as easy to see as the hover colour */
a:focus-visible {
  outline: 3px solid #8a1c55;
  outline-offset: 2px;
}

/* Lists: the 1st, 3rd, 5th ... goal in maroon */
.goals li:nth-child(odd) {
  color: #8a1c55;
}

/* Pseudo-elements: a green tick before each skill, quotation marks around the motto */
.skills li::before {
  content: "✓ ";
  color: #2e7d32;
  font-weight: bold;
}
.motto::before {
  content: "“";
}
.motto::after {
  content: "”";
}

/* A pseudo-element after a combinator: the paragraph right after an h1 starts with a maroon drop cap */
h1 + p::first-letter {
  float: left;
  font-size: 2.6em;
  line-height: 1;
  color: #8a1c55;
  margin-right: 4px;
}

/* Flexbox: Juan's project cards, one under the other; a media query turns them into a row on a narrow page */
.project-list {
  display: flex;
  flex-direction: column;
  gap: 0.5em;
  list-style-type: none;
  padding-left: 0;
}

/* Media query: on a page 900px wide or narrower, the nav items stand one under the other */
@media (max-width: 900px) {
  nav ul {
    flex-direction: column;
  }
}

/* Media query: on a narrow page the project cards sit side by side and wrap, to use the width that is left */
@media (max-width: 900px) {
  .project-list {
    flex-direction: row;
    flex-wrap: wrap;
  }
}

/* Flexbox: the contact form's fields, one under the other, with an even gap between them */
form {
  display: flex;
  flex-direction: column;
  gap: 0.75em;
}

